#include <bits/stdc++.h>
#include <omp.h>
using namespace std; using U=uint32_t; static const int N=25; static const U ALL=(1u<<25)-1;
using A=array<int8_t,N>;
U rot(U x,int k){k%=N;return ((x<<k)|(x>>(N-k)))&ALL;}
U star(U x){U y=0;for(int i=0;i<N;i++)if(x>>i&1)y|=1u<<((N-i)%N);return y;}
U mul(U a,U b){U y=0;for(int i=0;i<N;i++)if(a>>i&1)y^=rot(b,i);return y;}
U aff(U x,int a,int b){U y=0;for(int i=0;i<N;i++)if(x>>i&1)y|=1u<<((a*i+b)%N);return y;}
vector<int> mults(string cls){vector<int>v;if(cls=="center"){for(int a=1;a<N;a++)if(gcd(a,N)==1)v.push_back(a);}else if(cls=="unit")v={1,24};else if(cls=="five"){for(int a=1;a<N;a++)if(gcd(a,N)==1&&((5*a)%N==5||(5*a)%N==20))v.push_back(a);}return v;}
vector<U> orbit_reps(int w,const vector<int>&ms){vector<U>reps;unordered_set<U>seen;seen.reserve(6000000);if(w==0){reps.push_back(0);return reps;}U x=(1u<<w)-1;while(x<(1u<<N)){if(!seen.count(x)){U best=x;for(int a:ms)for(int b=0;b<N;b++)best=min(best,aff(x,a,b));if(best==x)reps.push_back(x);for(int a:ms)for(int b=0;b<N;b++)seen.insert(aff(x,a,b));}U c=x&-x,r=x+c;if(!r||r>=(1u<<N))break;x=(((r^x)>>2)/c)|r;}return reps;}
vector<pair<int,int>> stabilizer(U E,const vector<int>&ms){vector<pair<int,int>>s;for(int a:ms)for(int b=0;b<N;b++)if(aff(E,a,b)==E)s.push_back({a,b});return s;}
U canon_stab(U P,const vector<pair<int,int>>&st){U z=P;for(auto[a,b]:st)z=min(z,aff(P,a,b));return z;}
struct Key{U as=0,gs=0;bool operator<(Key const&o)const{return as!=o.as?as<o.as:gs<o.gs;}};
Key canon_pair(U as,U gs,const vector<int>&ms){Key z{UINT32_MAX,UINT32_MAX};for(int a:ms)for(int b=0;b<N;b++){Key q{aff(as,a,b),aff(gs,a,b)};if(q<z)z=q;}return z;}
struct AffSol{bool ok=false;U part=0;vector<U>basis;};
AffSol affine_solve(U D,U rhs){U rows[N]{};int aug[N]{};U Ds=star(D);for(int j=0;j<N;j++){U col=mul(1u<<j,Ds)^mul(D,star(1u<<j));for(int r=0;r<N;r++)if(col>>r&1)rows[r]|=1u<<j;}for(int r=0;r<N;r++)aug[r]=(rhs>>r)&1;int pr=0;vector<int>pc;for(int c=0;c<N&&pr<N;c++){int q=-1;for(int r=pr;r<N;r++)if(rows[r]>>c&1){q=r;break;}if(q<0)continue;swap(rows[pr],rows[q]);swap(aug[pr],aug[q]);for(int r=0;r<N;r++)if(r!=pr&&((rows[r]>>c)&1)){rows[r]^=rows[pr];aug[r]^=aug[pr];}pc.push_back(c);pr++;}for(int r=pr;r<N;r++)if(rows[r]==0&&aug[r])return{};bool isp[N]{};for(int c:pc)isp[c]=1;AffSol S;S.ok=true;for(int r=0;r<pr;r++)if(aug[r])S.part|=1u<<pc[r];for(int f=0;f<N;f++)if(!isp[f]){U v=1u<<f;for(int r=0;r<pr;r++)if(rows[r]>>f&1)v|=1u<<pc[r];S.basis.push_back(v);}return S;}
int paf(const A&x,int r){int s=0;for(int i=0;i<N;i++)s+=x[i]*x[(i+r)%N];return s;}
int qminG(const A&p,const A&c){int q=0;for(int r=1;r<=12;r++){int g=paf(p,r)+paf(c,r);q+=(g*g+(abs(g)&1))/2;}return q;}
int sgG(const A&p,const A&c){int s=0;for(int r=1;r<=12;r++){int g=paf(p,r)+paf(c,r);s+=g*g;}return s;}
bool crossok(const A&p,const A&c,const array<int,13>&target){for(int r=0;r<=12;r++){int h=0;for(int i=0;i<N;i++)h+=p[i]*c[(i-r+N)%N]+c[i]*p[(i-r+N)%N];if(h!=target[r])return false;}return true;}
vector<A> solve_other_mod3(const A&fixed,const vector<int>&ui,const array<int,13>&target){int nc=ui.size();int a[14][16]{},rhs[14]{};for(int j=0;j<nc;j++){int pos=ui[j];for(int r=0;r<=12;r++){int v=fixed[(pos+r)%N]+fixed[(pos-r+N)%N];v%=3;if(v<0)v+=3;a[r][j]=v;}a[13][j]=1;}for(int r=0;r<=12;r++){rhs[r]=target[r]%3;if(rhs[r]<0)rhs[r]+=3;}rhs[13]=1;int piv[16],rank=0;for(int col=0;col<nc;col++){int q=-1;for(int r=rank;r<14;r++)if(a[r][col]){q=r;break;}if(q<0)continue;for(int j=0;j<nc;j++)swap(a[rank][j],a[q][j]);swap(rhs[rank],rhs[q]);if(a[rank][col]==2){for(int j=0;j<nc;j++)a[rank][j]=(2*a[rank][j])%3;rhs[rank]=(2*rhs[rank])%3;}for(int r=0;r<14;r++)if(r!=rank&&a[r][col]){int f=a[r][col];for(int j=0;j<nc;j++){a[r][j]=(a[r][j]-f*a[rank][j])%3;if(a[r][j]<0)a[r][j]+=3;}rhs[r]=(rhs[r]-f*rhs[rank])%3;if(rhs[r]<0)rhs[r]+=3;}piv[rank++]=col;}for(int r=rank;r<14;r++)if(rhs[r])return{};bool isp[16]{};for(int r=0;r<rank;r++)isp[piv[r]]=1;vector<int>fr;for(int j=0;j<nc;j++)if(!isp[j])fr.push_back(j);vector<A>out;uint64_t M=1ull<<fr.size();for(uint64_t m=0;m<M;m++){int x[16]{};for(int k=0;k<(int)fr.size();k++)x[fr[k]]=(m>>k&1)?2:1;bool ok=true;for(int r=rank-1;r>=0;r--){int z=rhs[r];for(int f:fr)z=(z-a[r][f]*x[f])%3;if(z<0)z+=3;if(z!=1&&z!=2){ok=false;break;}x[piv[r]]=z;}if(!ok)continue;A u{};for(int j=0;j<nc;j++)u[ui[j]]=x[j]==1?1:-1;out.push_back(u);}return out;}
struct Stats{long long fixedtests=0,hmatch=0,qhit=0;int minSG=INT_MAX;};
Stats search_signs(U P,U C,int kp,int kc,const array<int,13>&target){vector<int>pi,ci;for(int i=0;i<N;i++){if(P>>i&1)pi.push_back(i);if(C>>i&1)ci.push_back(i);}Stats st;bool fixP=kp<=kc;const vector<int>&fi=fixP?pi:ci;const vector<int>&ui=fixP?ci:pi;int nf=fi.size(),neg=(nf-1)/2;U mask=neg?((1u<<neg)-1):0;bool first=true;while(true){if(!first&&neg==0)break;first=false;st.fixedtests++;A fixed{};for(int j=0;j<nf;j++)fixed[fi[j]]=(mask>>j&1)?-1:1;auto sols=solve_other_mod3(fixed,ui,target);for(auto&u:sols){A p=fixP?fixed:u,c=fixP?u:fixed;if(!crossok(p,c,target))continue;st.hmatch++;if(qminG(p,c)<=24){st.qhit++;st.minSG=min(st.minSG,sgG(p,c));}}if(neg==0)break;U cc=mask&-mask,rr=mask+cc;if(!rr||rr>=(1u<<nf))break;mask=(((rr^mask)>>2)/cc)|rr;}return st;}
struct Group{long long count=0;int minSG=INT_MAX;};
int main(int argc,char**argv){if(argc<5){cerr<<"usage: K16 kp t center|unit|five\n";return 2;}int K=atoi(argv[1]),kp=atoi(argv[2]),t=atoi(argv[3]);string cls=argv[4];if(K!=16||kp<1||kp>15||!(kp&1))return 2;int kc=K-kp;if(!(kc&1))return 2;int s=(cls=="center"?0:cls=="unit"?1:cls=="five"?5:-1);if(s<0)return 2;if((cls=="center"&&!(t&1))||(cls!="center"&&(t&1))||t<0||t>min(kp,kc))return 2;int raw=K-2*t,ew=min(raw,N-raw);bool comp=raw>12;auto ms=mults(cls);auto Es=orbit_reps(ew,ms);U rhs=0;if(s)rhs=(1u<<s)|(1u<<(N-s));array<int,13>target{};if(s==0)target[0]=2;else target[s]=1;atomic<long long>support{0},pt{0},hm{0},qh{0};map<Key,Group>groups;mutex gm;
#pragma omp parallel for schedule(dynamic,1)
for(int ei=0;ei<(int)Es.size();ei++){U E=Es[ei],D=comp?(ALL^E):E;auto S=affine_solve(D,rhs);if(!S.ok)continue;auto st=stabilizer(E,ms);long long ls=0,lpt=0,lh=0,lq=0;map<Key,Group>local;uint64_t M=1ull<<S.basis.size();for(uint64_t m=0;m<M;m++){U P=S.part;for(int j=0;j<(int)S.basis.size();j++)if(m>>j&1)P^=S.basis[j];if(__builtin_popcount(P)!=kp)continue;U C=P^D;if(__builtin_popcount(C)!=kc||canon_stab(P,st)!=P)continue;ls++;auto z=search_signs(P,C,kp,kc,target);lpt+=z.fixedtests;lh+=z.hmatch;lq+=z.qhit;if(z.qhit){Key k=canon_pair(ALL^P,ALL^C,ms);auto &g=local[k];g.count+=z.qhit;g.minSG=min(g.minSG,z.minSG);}}support+=ls;pt+=lpt;hm+=lh;qh+=lq;if(!local.empty()){lock_guard<mutex>lk(gm);for(auto&kv:local){auto &g=groups[kv.first];g.count+=kv.second.count;g.minSG=min(g.minSG,kv.second.minSG);}}}
cout<<"O58_K16_GROUPS kp="<<kp<<" kc="<<kc<<" t="<<t<<" cls="<<cls<<" diff_reps="<<Es.size()<<" support_orbits="<<support<<" fixedtests="<<pt<<" Hmatches="<<hm<<" qhits="<<qh<<" groups="<<groups.size()<<"\n";long long gc=0;for(auto&kv:groups){gc+=kv.second.count;cout<<"GROUP cls="<<cls<<" s="<<s<<" as="<<kv.first.as<<" gs="<<kv.first.gs<<" minSG="<<kv.second.minSG<<" count="<<kv.second.count<<"\n";}if(gc!=qh){cerr<<"GROUP_COUNT_MISMATCH qhits="<<qh<<" group_count="<<gc<<"\n";return 3;}return 0;}
